  @protected
  void sse_encode_local_file_copy_request(
    LocalFileCopyRequest self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_opt_list_prim_u_8_strict(self.sourcePath, serializer);
    sse_encode_opt_box_autoadd_i_32(self.sourceFd, serializer);
    sse_encode_opt_list_prim_u_8_strict(self.targetPath, serializer);
    sse_encode_opt_box_autoadd_i_32(self.targetFd, serializer);
    sse_encode_u_64(self.sourceOffset, serializer);
    sse_encode_opt_box_autoadd_u_64(self.length, serializer);
    sse_encode_opt_box_autoadd_local_file_identity(
      self.expectedSource,
      serializer,
    );
    sse_encode_u_64(self.maxBytes, serializer);
    sse_encode_u_32(self.timeoutMs, serializer);
  }

